        .sb-color-text { flex-grow: 1; min-width: 0; border: 1px solid #ccc; background: #fff; padding: 6px 8px; border-radius: 6px; font-family: monospace; font-size: 0.9em; outline: none; transition: 0.2s; box-sizing: border-box; }
