                (window.SillyTavern?.callGenericPopup || window.callGenericPopup)($wrap, 1, "", {okButton:false});
            }
            Logic.showPage('main', $wrap.find('.divine-scroll-content'), popup);
        } catch(e) { console.error(e); alert('System Error: '+e.message); }
    };

    const register = () => {
        if (typeof appendInexistentScriptButtons === 'function') {
            appendInexistentScriptButtons([{ name: BTN_NAME, visible: true }]);
            eventOn(getButtonEvent(BTN_NAME), initUI);
        } else {
            const $qr = $('#quick-reply-container, .quickReplyContainer');
            if ($qr.length && !$('#sanctuary-terminal-btn').length) {
                $qr.prepend(`<div id="sanctuary-terminal-btn" style="cursor:pointer;display:inline-block;padding:5px 10px;border:1px solid #00e5ff;margin:2px;color:#00e5ff;background:rgba(0,20,40,0.8);border-radius:3px;font-family:Consolas,monospace;">${BTN_NAME}</div>`);
                $('#sanctuary-terminal-btn').on('click', initUI);
            }
        }
    };
    setTimeout(register, 1200);
})();
